(function(){var images=[];var planImages=[];var activeSet;var currentIndex=0;var touchStartX=0;var modalEl=document.getElementById('lightboxModal');if(!modalEl)return;var modal=new bootstrap.Modal(modalEl);var modalImg=modalEl.querySelector('.lightbox-img');var counter=modalEl.querySelector('.lightbox-counter');document.querySelectorAll('#photo .portfolio-box').forEach(function(box,i){var source=box.querySelector('source');var img=box.querySelector('img');if(img){var srcset=source?source.getAttribute('srcset'):'';var fullSrc=srcset.split(',').pop().trim().split(' ')[0]||img.getAttribute('src');images.push(fullSrc);box.addEventListener('click',function(){activeSet=images;currentIndex=i;updateImage();modal.show();});}});document.querySelectorAll('.plan-zoom').forEach(function(el,i){var source=el.querySelector('source');var img=el.querySelector('img');if(img){var srcset=source?source.getAttribute('srcset'):'';var fullSrc=srcset.split(',').pop().trim().split(' ')[0]||img.getAttribute('src');planImages.push(fullSrc);el.addEventListener('click',function(){activeSet=planImages;currentIndex=i;updateImage();modal.show();});}});activeSet=images;if(images.length===0&&planImages.length===0)return;modalEl.querySelector('.lightbox-close').addEventListener('click',function(){modal.hide();});modalEl.querySelector('.lightbox-prev').addEventListener('click',function(){navigate(-1);});modalEl.querySelector('.lightbox-next').addEventListener('click',function(){navigate(1);});document.addEventListener('keydown',function(e){if(!modalEl.classList.contains('show'))return;if(e.key==='ArrowLeft')navigate(-1);else if(e.key==='ArrowRight')navigate(1);else if(e.key==='Escape')modal.hide();});modalEl.addEventListener('touchstart',function(e){touchStartX=e.changedTouches[0].screenX;},{passive:true});modalEl.addEventListener('touchend',function(e){var diff=e.changedTouches[0].screenX-touchStartX;if(Math.abs(diff)>50)navigate(diff>0?-1:1);},{passive:true});function navigate(dir){currentIndex=(currentIndex+dir+activeSet.length)%activeSet.length;updateImage();}
function updateImage(){modalImg.src=activeSet[currentIndex];counter.textContent=(currentIndex+1)+' / '+activeSet.length;}})();